function huffFreq(text){
  var f={};
  for(var i=0;i<text.length;i++){ var c=text[i]; f[c]=(f[c]||0)+1; }
  return f;
}
function cmpNode(x,y){ if(x.f!==y.f) return x.f-y.f; return x.seq-y.seq; }
function huffBuild(freqs){
  var items=[];
  for(var k in freqs){ if(freqs.hasOwnProperty(k)) items.push({ch:k, f:freqs[k], left:null, right:null}); }
  if(items.length===0) return null;
  if(items.length===1){ return {ch:items[0].ch, f:items[0].f, left:null, right:null}; }
  var seq=0; items.forEach(function(it){ it.seq=seq++; });
  items.sort(cmpNode);
  while(items.length>1){
    var a=items.shift(), b=items.shift();
    var node={ch:null, f:a.f+b.f, left:a, right:b, seq:seq++};
    items.push(node); items.sort(cmpNode);
  }
  return items[0];
}
function huffCodes(tree){
  var codes={};
  (function walk(node, prefix){
    if(node===null) return;
    if(node.ch!==null){ codes[node.ch]=(prefix===''?'0':prefix); return; }
    walk(node.left, prefix+'0'); walk(node.right, prefix+'1');
  })(tree, '');
  return codes;
}
function huffEncode(text){
  var f=huffFreq(text);
  var tree=huffBuild(f);
  var codes=huffCodes(tree);
  if(text.length===0) return {codes:codes, bits:''};
  var bits='';
  for(var i=0;i<text.length;i++) bits+=codes[text[i]];
  return {codes:codes, bits:bits};
}
function huffDecode(bits, codes){
  var rev={};
  for(var c in codes){ if(codes.hasOwnProperty(c)) rev[codes[c]]=c; }
  var out='', cur='';
  for(var i=0;i<bits.length;i++){
    cur+=bits[i];
    if(rev.hasOwnProperty(cur)){ out+=rev[cur]; cur=''; }
  }
  return out;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { huffFreq:huffFreq, huffBuild:huffBuild, huffCodes:huffCodes, huffEncode:huffEncode, huffDecode:huffDecode };
}
if (typeof window !== 'undefined') {
  window.HuffmanForgePure = { huffFreq:huffFreq, huffBuild:huffBuild, huffCodes:huffCodes, huffEncode:huffEncode, huffDecode:huffDecode };
}
